#!/usr/bin/env bash
set -euo pipefail
# test-dry-run.sh — smoke test for the dist/ channel.
# Covers: build (archive + SHA256SUMS) → init install (manifest, variant-B
# composition, selector agent, dev-.env exclusion, clean audit) → update (checksum
# verified) → [removed] branch + backup restore → tamper detection → overlay
# install preserving host files.  Exit 0 = all checks pass, exit 1 = failure.
#
# Usage: bash dist/test-dry-run.sh
# Run once after any change to dist/*.sh, before shipping to a real host.
#
# Dirty-tree guard: build.sh refuses to build a dirty checkout by default.
# We override it here with COUNCIL_ALLOW_DIRTY=1 so the dry-run can proceed
# despite our own uncommitted dist/*.sh edits.

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
# Honour the project's preferred temp root when it exists, but never assume
# /tmp/opencode is present on a fresh machine.
TMP_BASE="${TMPDIR_OPENCODE:-${TMPDIR:-/tmp}}"
mkdir -p "$TMP_BASE"
WORK="$(mktemp -d "$TMP_BASE/council-dryrun.XXXXXX")"
trap 'rm -rf "$WORK"' EXIT

fail() { echo "FAIL: $*"; exit 1; }
pass() { echo "  ok: $*"; }

TS=$(date +%s)
V1="smoke1-$TS"
V2="smoke2-$TS"

# ---------------------------------------------------------------------------
echo "[1/6] build: archive + SHA256SUMS ($V1)"
# ---------------------------------------------------------------------------
# Override dirty-tree guard so we can build with uncommitted dist/*.sh edits
COUNCIL_ALLOW_DIRTY=1 bash "$SCRIPT_DIR/build.sh" "$V1" >/dev/null
ARCH1="$SCRIPT_DIR/out/council-dist-$V1.tar.gz"
[[ -f "$ARCH1" ]] || fail "archive not built: $ARCH1"
[[ -f "$SCRIPT_DIR/out/SHA256SUMS" ]] || fail "SHA256SUMS not generated by build.sh"
(cd "$SCRIPT_DIR/out" && sha256sum -c SHA256SUMS >/dev/null) || fail "fresh build checksum mismatch"
# Keep a private copy: the second build.sh run wipes dist/out/.
mkdir -p "$WORK/keep"
cp "$ARCH1" "$WORK/keep/"
ARCH1="$WORK/keep/$(basename "$ARCH1")"
pass "archive built, SHA256SUMS generated and verifies"

# ---------------------------------------------------------------------------
echo "[2/6] init install into empty host"
# ---------------------------------------------------------------------------
mkdir -p "$WORK/d1" "$WORK/host1"
tar xzf "$ARCH1" -C "$WORK/d1"
( cd "$WORK/host1" && bash "$WORK/d1/council-dist/install.sh" \
    --target . --mode init --project-name dryrun-host >/dev/null )
[[ -f "$WORK/host1/.council/version.lock" ]] || fail ".council/version.lock missing"
[[ "$(cat "$WORK/host1/.council/version.lock")" == "$V1" ]] || fail "wrong pinned version"
[[ -f "$WORK/host1/.council/update.sh" ]] || fail ".council/update.sh missing"
[[ -f "$WORK/host1/tools/check_all.py" ]] || fail "core tools not installed"
[[ -f "$WORK/host1/AGENTS.md" ]] || fail "template AGENTS.md not installed"
[[ -f "$WORK/host1/docs-manifest.yaml" ]] || fail "docs-manifest.yaml not generated by installer"

# Variant-B: RU mirrors must be ABSENT on host
[[ ! -d "$WORK/host1/docs/ru" ]] || fail "docs/ru must NOT exist on host (Variant-B)"

# Variant-B: archive guard must exist
[[ -f "$WORK/host1/docs/en/archive/index.md" ]] || fail "docs/en/archive/index.md guard missing"

# Variant-B: defaults/translation.lock present, defaults/policy.yaml absent
[[ -f "$WORK/host1/defaults/translation.lock" ]] || fail "defaults/translation.lock missing"
[[ ! -f "$WORK/host1/defaults/policy.yaml" ]] || fail "defaults/policy.yaml must NOT exist on host (Variant-B)"

# Variant-B: selector agent
[[ -f "$WORK/host1/.opencode/agents/selector.md" ]] || fail "selector agent not installed"

# Variant-B: dev-.env exclusion
[[ ! -e "$WORK/host1/vendor/techdoc-translator/.env" ]] || fail "developer .env leaked into host"

# Templates purge: v0.x docs absent
[[ ! -d "$WORK/host1/templates/docs/en/operator-ingress" ]] || fail "operator-ingress must NOT be in templates (Variant-B)"
[[ ! -d "$WORK/host1/templates/docs/en/service-contract" ]] || fail "service-contract must NOT be in templates (Variant-B)"

# Templates: required files present (installed directly to host root, not under templates/)
[[ -f "$WORK/host1/CHANGELOGS/project-concept.changes.md" ]] || fail "project-concept.changes.md missing from host (installed directly)"

# CHANGELOGS/agents.changes.md must NOT be shipped as template
[[ ! -f "$WORK/host1/CHANGELOGS/agents.changes.md" ]] || fail "agents.changes.md must NOT be on host (Variant-B)"

if python3 -c "import yaml" 2>/dev/null; then
  ( cd "$WORK/host1" && python3 tools/check_all.py >/dev/null 2>&1 ) \
    || fail "check_all.py not clean on fresh install"
fi
pass "init install: variant-B composition correct, clean audit passes"

# ---------------------------------------------------------------------------
echo "[3/6] update to $V2 with checksum verification"
# ---------------------------------------------------------------------------
COUNCIL_ALLOW_DIRTY=1 bash "$SCRIPT_DIR/build.sh" "$V2" >/dev/null
mkdir -p "$WORK/upd"
cp "$SCRIPT_DIR/out/council-dist-$V2.tar.gz" "$WORK/upd/"
cp "$SCRIPT_DIR/out/SHA256SUMS" "$WORK/upd/"
# Capture output to a variable: `cmd | grep -q` with pipefail would report a
# spurious failure because grep exits early and the producer gets SIGPIPE.
OUT=$( cd "$WORK/host1" && bash .council/update.sh "$WORK/upd/council-dist-$V2.tar.gz" )
echo "$OUT" | grep -q "Checksum OK" || fail "checksum verification did not run"
[[ "$(cat "$WORK/host1/.council/version.lock")" == "$V2" ]] || fail "version not updated"
pass "update: checksum OK, version.lock=$V2"

# ---------------------------------------------------------------------------
echo "[4/6] [removed] branch + backup restore"
# ---------------------------------------------------------------------------
# Part A — manifest-less archive (current path: update.sh falls back to old
# manifest).  This tests the removal warning but not the UNION fix.
mkdir -p "$WORK/nomani" "$WORK/variant"
tar xzf "$WORK/upd/council-dist-$V2.tar.gz" -C "$WORK/nomani"
rm -f "$WORK/nomani/council-dist/core-manifest.txt"
( cd "$WORK/nomani" && tar czf "$WORK/variant/council-dist-$V2.tar.gz" council-dist )
# Pretend the host has an extra core file: create it + list it in the manifest
echo "core" > "$WORK/host1/tools/smoke-extra.txt"
echo "tools/smoke-extra.txt" >> "$WORK/host1/.council/core-manifest.txt"
OUT=$( cd "$WORK/host1" && bash .council/update.sh "$WORK/variant/council-dist-$V2.tar.gz" --force )
echo "$OUT" | grep -q "SHA256SUMS not found" || fail "missing-checksum warning not printed"
echo "$OUT" | grep -q "\[removed\] tools/smoke-extra.txt" || fail "[removed] not reported"
[[ ! -e "$WORK/host1/tools/smoke-extra.txt" ]] || fail "removed file still present"
BACKUP=$( ls -dt "$WORK/host1/.council/backup-"* | head -1 )
( cd "$WORK/host1" && cp -R "$BACKUP"/. . )
[[ -f "$WORK/host1/tools/smoke-extra.txt" ]] || fail "restore from backup failed"
pass "removal warned (backup path shown), file deleted, restore works (manifest-less)"

# Part B — manifest-present archive: create an orphan on the host and update
# to V2 (which has a different manifest).  This is the real UNION path that
# exercises MF-3: a file listed in old manifest but absent from new manifest
# must be [removed]'d even when the new archive has its own manifest.
echo "core" > "$WORK/host1/tools/smoke-extra2.txt"
echo "tools/smoke-extra2.txt" >> "$WORK/host1/.council/core-manifest.txt"
OUT2=$( cd "$WORK/host1" && bash .council/update.sh "$WORK/upd/council-dist-$V2.tar.gz" --force 2>&1 ) || true
echo "$OUT2" | grep -q "\[removed\] tools/smoke-extra2.txt" || fail "[removed] NOT reported for manifest-present update (MF-3 fix missing)"
[[ ! -e "$WORK/host1/tools/smoke-extra2.txt" ]] || fail "removed file still present after manifest-present update (MF-3)"
# Verify backup preserved the orphan (find newest by name, not mtime — Part A restore
# updates old backup dir mtime which would confuse ls -dt)
BACKUP2=$( ls -1d "$WORK/host1/.council/backup-"* | sort -t- -k2 -n | tail -1 )
[[ -f "$BACKUP2/tools/smoke-extra2.txt" ]] || fail "orphan not backed up (MF-3 fix missing)"
pass "removal works with manifest-present archive (UNION path, MF-3)"

# ---------------------------------------------------------------------------
echo "[5/6] tamper detection (corrupted archive refused)"
# ---------------------------------------------------------------------------
mkdir -p "$WORK/tamper"
cp "$WORK/upd/council-dist-$V2.tar.gz" "$WORK/tamper/"
cp "$WORK/upd/SHA256SUMS" "$WORK/tamper/"
echo "corrupted" >> "$WORK/tamper/council-dist-$V2.tar.gz"
if ( cd "$WORK/host1" && bash .council/update.sh "$WORK/tamper/council-dist-$V2.tar.gz" --force ) 2>&1; then
  fail "corrupted archive was accepted"
fi
pass "corrupted archive refused (checksum failure)"

# ---------------------------------------------------------------------------
echo "[6/6] overlay install preserves host files + broken install precheck"
# ---------------------------------------------------------------------------
mkdir -p "$WORK/host2"
echo "HOST CUSTOM AGENTS CONTENT" > "$WORK/host2/AGENTS.md"
echo "keep me" > "$WORK/host2/README.md"
mkdir -p "$WORK/d2"
tar xzf "$ARCH1" -C "$WORK/d2"
OUT=$( cd "$WORK/host2" && bash "$WORK/d2/council-dist/install.sh" \
  --target . --mode overlay --project-name dryrun-overlay )
echo "$OUT" | grep -q "OVERLAY mode" || fail "overlay mode note missing"
grep -q "HOST CUSTOM AGENTS CONTENT" "$WORK/host2/AGENTS.md" || fail "overlay overwrote host file"
[[ -f "$WORK/host2/README.md" ]] || fail "overlay deleted host file"
[[ -f "$WORK/host2/tools/check_all.py" ]] || fail "overlay did not install core"
pass "overlay: note printed, host files preserved, core installed"

# Additional: broken install test — core/ deleted → must exit non-zero
# and must NOT print 'installed successfully'
mkdir -p "$WORK/broken" "$WORK/broken-host"
tar xzf "$ARCH1" -C "$WORK/broken"
rm -rf "$WORK/broken/council-dist/core"  # Remove core/ to simulate broken archive
OUT_BROKEN=$( cd "$WORK/broken" && bash council-dist/install.sh --target "$WORK/broken-host" --mode init --project-name broken 2>&1 || true )
if echo "$OUT_BROKEN" | grep -q "installed successfully"; then
  fail "broken install should NOT print 'installed successfully'"
fi
pass "broken install: core/ absent → exits non-zero, no success banner"

echo ""
echo "DRY-RUN PASSED"
